import{_ as r,C as i,o as t,c as l,a2 as a,b as s,w as n,a as d,E as c,a3 as h}from"./chunks/framework.DToEn73J.js";const k=JSON.parse('{"title":"会话状态","description":"","frontmatter":{"title":"会话状态","chapter":"3.4","order":4,"summary":"设计 Session store 与 Checkpoint 粒度，实现多轮对话与多次运行的可恢复状态与中断取消语义。"},"headers":[],"relativePath":"03-context-memory/session-state.md","filePath":"03-context-memory/session-state.md","lastUpdated":1787724133000}'),p={name:"03-context-memory/session-state.md"};function m(u,e,g,_,A,E){const o=i("Mermaid");return t(),l("div",null,[e[1]||(e[1]=a('<h1 id="会话状态" tabindex="-1">会话状态 <a class="header-anchor" href="#会话状态" aria-label="Permalink to &quot;会话状态&quot;">​</a></h1><h2 id="是什么" tabindex="-1">是什么 <a class="header-anchor" href="#是什么" aria-label="Permalink to &quot;是什么&quot;">​</a></h2><p>会话状态管理解决 Agent 在多次运行、多轮对话间“暂停后能接着跑”的问题，核心是 Session store 与 Checkpoint 的设计，使中断、取消、恢复都有确定状态可依据。</p><h2 id="怎么做" tabindex="-1">怎么做 <a class="header-anchor" href="#怎么做" aria-label="Permalink to &quot;怎么做&quot;">​</a></h2><p><strong>Session store 设计</strong>：以 <code>session_id</code> 为键，持久化 <code>{messages, plan, tool_call_log, memory_refs, status}</code>。状态与消息流分离——消息进 Context Window，状态进 store。</p><p><strong>Checkpoint 粒度</strong>按可恢复性权衡：</p><table tabindex="0"><thead><tr><th>粒度</th><th>恢复成本</th><th>适用</th></tr></thead><tbody><tr><td>每轮（turn）</td><td>低</td><td>交互式对话</td></tr><tr><td>每工具调用</td><td>中</td><td>长任务、需 Kill Switch</td></tr><tr><td>每子计划</td><td>高</td><td>Plan-and-Execute 大任务</td></tr></tbody></table><p><strong>中断/取消语义</strong>：</p><ul><li>取消（cancel）：终止循环，保留已完成 Checkpoint，状态置 <code>cancelled</code>，可重启续跑。</li><li>中断（interrupt）：人工介入点（如权限确认），保留挂起点，恢复后从 Checkpoint 继续，不全量重跑。</li></ul>',9)),(t(),s(h,null,{default:n(()=>[c(o,{id:"mermaid-83",class:"mermaid",graph:"stateDiagram-v2%0A%20%20%20%20%5B*%5D%20--%3E%20Running%0A%20%20%20%20Running%20--%3E%20Checkpointed%3A%20%E8%BE%BE%E5%88%B0%E7%B2%92%E5%BA%A6%0A%20%20%20%20Checkpointed%20--%3E%20Running%3A%20%E6%81%A2%E5%A4%8D%0A%20%20%20%20Running%20--%3E%20Interrupted%3A%20%E9%9C%80%E4%BA%BA%E5%B7%A5%0A%20%20%20%20Interrupted%20--%3E%20Running%3A%20%E7%A1%AE%E8%AE%A4%E5%90%8E%0A%20%20%20%20Running%20--%3E%20Cancelled%3A%20%E7%94%A8%E6%88%B7%E5%8F%96%E6%B6%88%0A%20%20%20%20Cancelled%20--%3E%20Running%3A%20%E9%87%8D%E5%90%AF%E7%BB%AD%E8%B7%91%0A"})]),fallback:n(()=>[...e[0]||(e[0]=[d(" Loading... ",-1)])]),_:1})),e[2]||(e[2]=a('<h2 id="为什么" tabindex="-1">为什么 <a class="header-anchor" href="#为什么" aria-label="Permalink to &quot;为什么&quot;">​</a></h2><p>缺乏 Checkpoint，一次崩溃或取消意味着从零重跑整段任务，成本不可接受；缺乏明确的取消语义则无法安全地在长任务中插入人工审批。</p><h2 id="常见误区" tabindex="-1">常见误区 <a class="header-anchor" href="#常见误区" aria-label="Permalink to &quot;常见误区&quot;">​</a></h2><ul><li>把全部状态塞进消息历史，导致恢复时无法区分“已执行”与“待执行”。</li><li>Checkpoint 过粗，恢复需重放大量已完成的工具调用。</li></ul><h2 id="业界实现对照" tabindex="-1">业界实现对照 <a class="header-anchor" href="#业界实现对照" aria-label="Permalink to &quot;业界实现对照&quot;">​</a></h2><ul><li>LangGraph：<code>Checkpointer</code> 持久化 graph state，支持 <code>interrupt</code>/<code>resume</code>（<a href="https://langchain-ai.github.io/langgraph/concepts/persistence/" target="_blank" rel="noreferrer">docs</a>）。</li><li>OpenAI Agents SDK：<code>Session</code> 与 <code>trace</code> 维护运行状态（<a href="https://openai.github.io/openai-agents-python/" target="_blank" rel="noreferrer">docs</a>）。</li></ul><h2 id="延伸阅读" tabindex="-1">延伸阅读 <a class="header-anchor" href="#延伸阅读" aria-label="Permalink to &quot;延伸阅读&quot;">​</a></h2><ul><li><a href="/fk-ai-agent/03-context-memory/context-window">Context Window 管理</a></li><li><a href="/fk-ai-agent/03-context-memory/long-term-memory">长期记忆</a></li><li><a href="/fk-ai-agent/03-context-memory/context-engineering">上下文工程</a></li><li><a href="/fk-ai-agent/05-safety-governance/kill-switch">Kill Switch 安全停机</a></li></ul><hr><p><em>最后核实日期：2026-08-26</em></p>',10))])}const b=r(p,[["render",m]]);export{k as __pageData,b as default};
